/** Calendar day used for publish gating (matches content calendar timezone). */
export const PUBLISH_TIMEZONE = 'Asia/Kolkata';

/** Today's date as `YYYY-MM-DD` in the publish timezone. */
export function getTodayDateString(now: Date = new Date()): string {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: PUBLISH_TIMEZONE,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(now);
}

export function isPostPublished(post: BlogPost, now: Date = new Date()): boolean {
  return post.publishDate <= getTodayDateString(now);
}

/** Published posts only, newest first. */
export function getPublishedPosts(now: Date = new Date()): BlogPost[] {
  return blogPosts
    .filter((post) => isPostPublished(post, now))
    .sort((a, b) => b.publishDate.localeCompare(a.publishDate));
}

export function formatPublishDate(isoDate: string): string {
  const [year, month, day] = isoDate.split('-').map(Number);
  if (!year || !month || !day) return isoDate;
  return new Date(year, month - 1, day).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

/** Returns a post only if it exists and is already published. */
export function getBlogPostBySlug(slug: string, now: Date = new Date()): BlogPost | undefined {
  const post = blogPosts.find((p) => p.slug === slug);
  if (!post || !isPostPublished(post, now)) return undefined;
  return post;
}

export function getRelatedPosts(
  currentSlug: string,
  category: string,
  limit = 3,
  now: Date = new Date()
): BlogPost[] {
  const published = getPublishedPosts(now).filter((p) => p.slug !== currentSlug);
  const sameCategory = published.filter((p) => p.category === category);
  if (sameCategory.length >= limit) {
    return sameCategory.slice(0, limit);
  }
  const others = published.filter((p) => p.category !== category);
  return [...sameCategory, ...others].slice(0, limit);
}

export function getAllCategories(now: Date = new Date()): string[] {
  const cats = new Set(getPublishedPosts(now).map((p) => p.category));
  return Array.from(cats);
}
